### brain.go

```go
package main

import (
	"fmt"
	"math/rand"
	"os"
	"strings"
	"sync"
	"time"
)

type Node struct {
	ID    string
	Links map[*Node]uint64
}

var (
	Universe      = make(map[string]*Node)
	UniverseMutex sync.RWMutex
	ActiveContext [3]*Node
)

func Initialize() {
	UniverseMutex.Lock()
	defer UniverseMutex.Unlock()

	root := &Node{
		ID:    "ROOT",
		Links: make(map[*Node]uint64),
	}
	Universe["ROOT"] = root

	ActiveContext[0] = root
	ActiveContext[1] = root
	ActiveContext[2] = root

	rand.Seed(time.Now().UnixNano())
}

func Intern(symbol string) *Node {
	UniverseMutex.Lock()
	defer UniverseMutex.Unlock()

	if node, exists := Universe[symbol]; exists {
		return node
	}

	newNode := &Node{
		ID:    symbol,
		Links: make(map[*Node]uint64),
	}
	Universe[symbol] = newNode
	return newNode
}

func Ingest(r rune) {
	symbol := string(r)
	node := Intern(symbol)
	Observe(node)
}

func Observe(current *Node) {
	prev := ActiveContext[2]

	UniverseMutex.Lock()
	linkCount, exists := prev.Links[current]
	if exists {
		prev.Links[current] = linkCount + 1
	} else {
		prev.Links[current] = 1
	}
	UniverseMutex.Unlock()

	learningRate := uint64(1)
	if CalculateConfidence(prev) {
		learningRate = 2
	}

	UniverseMutex.Lock()
	prev.Links[current] += learningRate
	UniverseMutex.Unlock()

	Shift(current)

	Decay()

	if prev.Links[current] > 100 {
		CheckCompress(prev, current)
	}

	Refactor(prev)
	Conflict(prev)
	GarbageCollect()
}

func CalculateConfidence(node *Node) bool {
	UniverseMutex.RLock()
	defer UniverseMutex.RUnlock()

	if len(node.Links) == 0 {
		return false
	}

	var max uint64
	var sum uint64
	for _, count := range node.Links {
		sum += count
		if count > max {
			max = count
		}
	}

	if sum == 0 {
		return false
	}

	return max*10 > sum*9
}

func Decay() {
	UniverseMutex.Lock()
	defer UniverseMutex.Unlock()

	for _, node := range Universe {
		for target, count := range node.Links {
			newCount := (count * 9) / 10
			if newCount == 0 {
				delete(node.Links, target)
			} else {
				node.Links[target] = newCount
			}
		}
	}
}

func Predict() {
	current := ActiveContext[2]

	UniverseMutex.RLock()
	if len(current.Links) == 0 {
		UniverseMutex.RUnlock()
		return
	}

	type LinkOption struct {
		Target *Node
		Count  uint64
	}
	var options []LinkOption
	var sum uint64

	for target, count := range current.Links {
		options = append(options, LinkOption{target, count})
		sum += count
	}
	UniverseMutex.RUnlock()

	if sum == 0 {
		return
	}

	next := Roulette(options, sum)

	if rand.Intn(100) == 0 {
		next = Noise()
	}

	fmt.Print(next.ID)

	Shift(next)
}

func Roulette(options []struct{Target *Node; Count uint64}, sum uint64) *Node {
	pick := uint64(rand.Int63n(int64(sum)))
	var currentSum uint64
	for _, opt := range options {
		currentSum += opt.Count
		if pick < currentSum {
			return opt.Target
		}
	}
	return options[0].Target
}

func Noise() *Node {
	UniverseMutex.RLock()
	defer UniverseMutex.RUnlock()

	idx := rand.Intn(len(Universe))
	i := 0
	for _, node := range Universe {
		if i == idx {
			return node
		}
		i++
	}
	return ActiveContext[2] 
}

func Shift(node *Node) {
	ActiveContext[0] = ActiveContext[1]
	ActiveContext[1] = ActiveContext[2]
	ActiveContext[2] = node
}

func CheckCompress(a, b *Node) {
	UniverseMutex.Lock()
	defer UniverseMutex.Unlock()

	count := a.Links[b]
	if count > 100 {
		Compress(a, b)
	}
}

func Compress(a, b *Node) {
	newID := a.ID + b.ID
	if _, exists := Universe[newID]; exists {
		return
	}

	newNode := &Node{
		ID:    newID,
		Links: make(map[*Node]uint64),
	}
	Universe[newID] = newNode

	newNode.Links = b.Links 

	delete(a.Links, b)
	a.Links[newNode] = 100 
}

func Refactor(node *Node) {
	UniverseMutex.Lock()
	defer UniverseMutex.Unlock()

	if len(node.Links) == 1 {
		for target, count := range node.Links {
			if count > 1000 { 
				Merge(node, target)
			}
		}
	}
}

func Merge(parent, child *Node) {
	parent.ID = parent.ID + child.ID
	parent.Links = child.Links
	delete(Universe, child.ID)
}

func Conflict(node *Node) {
	UniverseMutex.Lock()
	defer UniverseMutex.Unlock()

	if len(node.Links) < 2 {
		return
	}

	var max1, max2 uint64

	for _, count := range node.Links {
		if count > max1 {
			max2 = max1
			max1 = count
		} else if count > max2 {
			max2 = count
		}
	}

	if max1 > 0 && max1 == max2 {
		node.ID = node.ID + "_SPLIT" 
	}
}

func GarbageCollect() {
	UniverseMutex.Lock()
	defer UniverseMutex.Unlock()

	for id, node := range Universe {
		if len(node.Links) == 0 && id != "ROOT" {
			delete(Universe, id)
		}
	}
}

func Thought() {
	current := ActiveContext[2]
	path := make(map[*Node]bool)

	for {
		if path[current] {
			break
		}
		path[current] = true

		UniverseMutex.RLock()
		if len(current.Links) == 0 {
			UniverseMutex.RUnlock()
			break
		}

		var best *Node
		var max uint64
		for t, c := range current.Links {
			if c > max {
				max = c
				best = t
			}
		}
		UniverseMutex.RUnlock()

		if best == nil {
			break
		}
		current = best
	}
}

func Serialize(filename string) {
	UniverseMutex.RLock()
	defer UniverseMutex.RUnlock()

	f, _ := os.Create(filename)
	defer f.Close()

	for _, node := range Universe {
		line := node.ID + "|"
		for target, count := range node.Links {
			line += fmt.Sprintf("%s:%d,", target.ID, count)
		}
		f.WriteString(line + "\n")
	}
}

func Deserialize(filename string) {
	UniverseMutex.Lock()
	defer UniverseMutex.Unlock()

	data, _ := os.ReadFile(filename)
	lines := strings.Split(string(data), "\n")

	tempLinks := make(map[string]map[string]uint64)

	for _, line := range lines {
		if line == "" { continue }
		parts := strings.Split(line, "|")
		id := parts[0]

		node := &Node{ID: id, Links: make(map[*Node]uint64)}
		Universe[id] = node

		if len(parts) > 1 {
			linksStr := parts[1]
			linkMap := make(map[string]uint64)
			linkPairs := strings.Split(linksStr, ",")
			for _, pair := range linkPairs {
				if pair == "" { continue }
				kv := strings.Split(pair, ":")
				if len(kv) == 2 {
					var count uint64
					fmt.Sscanf(kv[1], "%d", &count)
					linkMap[kv[0]] = count
				}
			}
			tempLinks[id] = linkMap
		}
	}

	for srcID, links := range tempLinks {
		srcNode := Universe[srcID]
		for targetID, count := range links {
			if targetNode, ok := Universe[targetID]; ok {
				srcNode.Links[targetNode] = count
			}
		}
	}
}

func Query(input string) {
	for _, r := range input {
		Ingest(r)
	}
}

